<script setup lang="ts">
import {computed,ref,reactive,toRefs,watch,onMounted,onUnmounted} from 'vue'
import type {PriceHistoryFilters} from '@/data/logisticsPriceSession'
import {realChannelHistories,comparedVersions,recordedYearLow,recordedPeriod,publicationTime,publicationDate,priorityPriceCountries,type RealPriceSnapshot,type ChannelPriceHistory,type HistoryPoint} from '@/data/logisticsRealPriceHistory'
import catalog from '@/data/logisticsPriceCountryCatalog.json'
import {channelSearchTerms,searchCountryChannels,type SearchableChannelHistory} from '@/data/logisticsChannelSearch'
import {attributeChannelHistories,priceHistoryAttributes,majorChannelCategories,hasWorkbookCountry} from '@/data/logisticsMajorChannelHistory'
import FinanceCountrySelect from '@/components/finance/FinanceCountrySelect.vue'
const props=defineProps<{snapshot:RealPriceSnapshot;refreshing:boolean;error:string;checkedAt?:string;state?:PriceHistoryFilters}>()
const emit=defineEmits<{workspace:[mode:'base'|'rules'];refresh:[]}>()
const priority=new Map<string,number>(priorityPriceCountries.map(([code],i)=>[code,i]))
const countryOptions=catalog.countries.map(c=>({country:c.name,code:c.code,stageLabel:priority.has(c.code)?'重点国家':'其他国家/地区'})).sort((a,b)=>(priority.get(a.code)??999)-(priority.get(b.code)??999)||a.country.localeCompare(b.country,'zh-CN'))
const {country,attribute,weight,comparison,search,page}=toRefs(reactive(props.state??{country:'德国',attribute:'普货/服装',weight:1,comparison:'currentPrevious',search:'',page:1}))
const detailsOpen=ref(false),selected=ref('')
const countryCode=computed(()=>catalog.countries.find(c=>c.name===country.value)?.code||'')
const attributes=computed(()=>priceHistoryAttributes(props.snapshot))
const isMajorAttribute=computed(()=>hasWorkbookCountry(countryCode.value)&&majorChannelCategories.includes(attribute.value))
watch(attributes,values=>{if(!values.includes(attribute.value))attribute.value=values[0]!},{immediate:true})
const shortlist=computed(()=>attributeChannelHistories(props.snapshot,countryCode.value,weight.value,attribute.value))
const isSearching=computed(()=>channelSearchTerms(search.value).length>0)
const countryHistory=computed(()=>isSearching.value?realChannelHistories(props.snapshot,countryCode.value,weight.value):[])
const rows=computed<SearchableChannelHistory[]>(()=>isSearching.value?searchCountryChannels(props.snapshot,countryCode.value,weight.value,search.value,countryHistory.value):shortlist.value.rows.map(r=>({...r,isMajor:isMajorAttribute.value})))
const pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/6)))
const visibleRows=computed(()=>rows.value.slice((page.value-1)*6,page.value*6))
watch([country,attribute,weight,search],()=>{page.value=1;selected.value=''})
watch(pages,n=>{page.value=Math.min(page.value,n)})
const statistics=computed(()=>new Map(rows.value.map(r=>[r.key,{comparison:comparedVersions(r,comparison.value),low:recordedYearLow(r,props.snapshot.capturedAt),period:recordedPeriod(r,'2025-01-01','2026-10-01',props.snapshot.capturedAt)}])))
const compare=(r:ChannelPriceHistory)=>statistics.value.get(r.key)!.comparison
const low=(r:ChannelPriceHistory)=>statistics.value.get(r.key)!.low
const period=(r:ChannelPriceHistory)=>statistics.value.get(r.key)!.period
const f=(n:number|null|undefined)=>n==null?'—':n.toFixed(2)
const signed=(n:number|null|undefined)=>n==null?'—':(n>0?'+':'')+n.toFixed(2)
const pct=(n:number|null|undefined)=>n==null?'—':(n>0?'+':'')+n.toFixed(1)+'%'
const tone=(n:number|null|undefined)=>n==null||n===0?'flat':n>0?'up':'down'
const comparisonLabel=computed(()=>comparison.value==='currentPrevious'?'本版较上一版':comparison.value==='currentOlder'?'本版较前两版':'上一版较前两版')
const counts=computed(()=>{const changes=rows.value.map(r=>compare(r).change);return{up:changes.filter(n=>n!=null&&n>0).length,down:changes.filter(n=>n!=null&&n<0).length,same:changes.filter(n=>n===0).length,missing:changes.filter(n=>n==null).length}})
const chartPoints=(r:ChannelPriceHistory)=>r.history.slice(-5)
const extent=(r:ChannelPriceHistory)=>{const values=chartPoints(r).flatMap(p=>p.price==null?[]:[p.price]);if(low(r))values.push(low(r)!.price!);const lo=values.length?Math.min(...values):0,hi=values.length?Math.max(...values):1;const pad=Math.max(1,(hi-lo)*.2);return{lo:Math.max(0,lo-pad),hi:hi+pad}}
const cx=(r:ChannelPriceHistory,i:number)=>40+i*376/Math.max(1,chartPoints(r).length-1)
const cy=(r:ChannelPriceHistory,n:number)=>110-(n-extent(r).lo)/(extent(r).hi-extent(r).lo)*88
const curve=(r:ChannelPriceHistory)=>{let path='',previous=false;chartPoints(r).forEach((p,i)=>{if(p.price==null){previous=false;return}path+=previous?` H${cx(r,i)} V${cy(r,p.price)}`:` M${cx(r,i)},${cy(r,p.price)}`;previous=true});return path}
const color=(r:ChannelPriceHistory)=>compare(r).change==null?'#8094a4':compare(r).change!<0?'#478d79':'#d38b3d'
const isLow=(r:ChannelPriceHistory,p:HistoryPoint|undefined)=>p?.price!=null&&p.date.slice(0,4)===publicationDate(props.snapshot.capturedAt).slice(0,4)&&p.price===low(r)?.price
const openDetails=(key='')=>{selected.value=key;detailsOpen.value=true}
const detailRows=computed(()=>selected.value?rows.value.filter(r=>r.key===selected.value):rows.value)
const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape')detailsOpen.value=false}
onMounted(()=>window.addEventListener('keydown',closeOnEscape))
onUnmounted(()=>window.removeEventListener('keydown',closeOnEscape))
</script>
<template>
<div class="logistics-page charts-screen"><main>
 <nav class="workspace-switch" aria-label="物流工作区"><button @click="emit('workspace','base')">基础资料设置</button><button @click="emit('workspace','rules')">运费规则列表</button><button class="active">渠道价格变动</button></nav>
 <section class="rule-workspace-card chart-workspace">
  <header class="chart-title"><div><h2>渠道价格变动 <small class="real-badge">真实已发布价格</small></h2><p>默认展示表内重点渠道 · 搜索可查看其他渠道 · CNY / 票</p></div><div class="head-actions"><span class="auto-update" :title="'价格快照读取于 '+publicationTime(snapshot.capturedAt)">按需更新<small>{{checkedAt?'检查于 '+publicationTime(checkedAt):'快照于 '+publicationTime(snapshot.capturedAt)}}</small></span><button class="refresh-button" :disabled="refreshing" :aria-busy="refreshing" @click="emit('refresh')">{{refreshing?'刷新中…':'刷新最新价格'}}</button><button class="detail-button" @click="openDetails()">价格明细 ↗</button></div></header>
  <p v-if="error" class="load-error" role="alert">{{error}}；当前保留上次成功读取的数据。</p>
  <div class="chart-filters"><div class="trend-country-field"><span>国家/地区</span><FinanceCountrySelect v-model="country" :countries="countryOptions"/></div><label>物流属性<span v-if="isSearching" class="search-attribute">全部属性</span><select v-else v-model="attribute" aria-label="物流属性"><option v-for="a in attributes" :key="a" :value="a">{{a}}</option></select></label><label>重量<select v-model="weight" aria-label="重量"><option :value="0.5">0.5 kg</option><option :value="1">1 kg</option><option :value="2">2 kg</option></select></label><label>比较<select v-model="comparison" aria-label="比较版本"><option value="currentPrevious">本版 vs 上一版</option><option value="currentOlder">本版 vs 前两版</option><option value="previousOlder">上一版 vs 前两版</option></select></label><div class="channel-search-field"><input v-model="search" class="channel-search" placeholder="模糊搜索其他渠道" aria-label="搜索渠道或分区" @keydown.esc="search=''"/><button v-if="search" class="clear-search" @click="search=''" aria-label="清空渠道搜索">×</button></div></div>
  <div class="results-bar"><span>{{country}} · {{isSearching?'搜索结果':attribute+(isMajorAttribute?' · 表内重点渠道':' · 系统渠道')}} {{rows.length}} 条 / 分区 <small>{{isSearching?'搜索当前国家全部物流属性 · 清空恢复属性筛选':(isMajorAttribute?'按原表顺序 · 各分区独立比较':'按系统物流属性筛选 · 各分区独立比较')}}</small></span><div class="counts"><span class="up">↑ {{counts.up}} 涨价</span><span class="down">↓ {{counts.down}} 降价</span><span>{{counts.same}} 不变</span><span v-if="counts.missing">{{counts.missing}} 暂不可比</span></div></div>
  <aside v-if="!isSearching&&isMajorAttribute&&shortlist.pending.length" class="watch-pending" aria-label="渠道对应说明"><b>说明</b><p v-for="item in shortlist.pending" :key="item.cell">{{item.name}}：{{item.reason}}。</p></aside>
  <div class="chart-grid" v-if="visibleRows.length">
   <article class="channel-card" v-for="r in visibleRows" :key="r.key">
    <div class="card-heading"><div><h3 :title="'系统渠道：'+r.channel.name">{{r.candidateFor?.length?r.channel.name:r.watchName}}</h3><small class="channel-meta">{{r.tableAttribute}} · {{r.channel.provider}} · {{r.region}}<span v-if="isSearching&&r.isMajor" class="major-tag">重点</span></small><small v-if="r.candidateFor?.length" class="candidate-note">待确认对应：{{r.candidateFor.join('、')}}</small></div></div>
    <div class="card-price"><div><strong :class="{'annual-low-text':isLow(r,r.current)}"><small v-if="r.current?.price!=null">¥</small> {{f(r.current?.price)}}</strong><span>{{r.current?.price==null?r.current?.reason:'本版 V'+r.current.number+' · '+r.current.date}}</span></div><div class="card-change" :class="tone(compare(r).change)"><b>{{compare(r).change==null?'暂不可比':compare(r).change===0?'不变':signed(compare(r).change)+' 元'}}</b><span>{{pct(compare(r).percent)}} · {{comparisonLabel}}</span></div></div>
    <svg class="channel-chart" viewBox="0 0 454 147" role="img" :aria-label="r.channel.name+' '+r.region+'最近五个已发布版本的价格趋势'">
      <g v-for="v in [extent(r).lo,(extent(r).lo+extent(r).hi)/2,extent(r).hi]" :key="v"><line x1="40" x2="416" :y1="cy(r,v)" :y2="cy(r,v)" stroke="#e9edf1"/><text x="28" :y="cy(r,v)+4" text-anchor="end" class="axis">{{v.toFixed(1)}}</text></g>
      <line v-if="low(r)" x1="40" x2="416" :y1="cy(r,low(r)!.price!)" :y2="cy(r,low(r)!.price!)" stroke="#dc3e3e" stroke-dasharray="4 4" opacity=".6"/><path :d="curve(r)" fill="none" :stroke="color(r)" stroke-width="2.6" stroke-linejoin="round"/>
      <g v-for="(v,i) in chartPoints(r)" :key="v.id" tabindex="0"><title>{{publicationTime(v.timestamp)}} · V{{v.number}} · {{v.price==null?v.reason:'¥'+f(v.price)}} · {{v.file}}</title>
       <template v-if="v.price!=null"><circle :cx="cx(r,i)" :cy="cy(r,v.price)" r="9" fill="transparent"/><circle :cx="cx(r,i)" :cy="cy(r,v.price)" :r="v.id===compare(r).from?.id||v.id===compare(r).to?.id?4.5:3" :fill="isLow(r,v)?'#dc3e3e':v.id===compare(r).from?.id||v.id===compare(r).to?.id?color(r):'white'" :stroke="isLow(r,v)?'#dc3e3e':color(r)" stroke-width="1.8"/><text :x="cx(r,i)" :y="cy(r,v.price)-12" text-anchor="middle" class="point-label" :class="{'annual-low-point':isLow(r,v)}">{{f(v.price)}}</text></template>
       <text v-else :x="cx(r,i)" y="66" text-anchor="middle" class="date">无适用价</text><text :x="cx(r,i)" y="135" text-anchor="middle" class="date">{{v.date.slice(5).replace('-','/')}} · V{{v.number}}</text>
      </g>
    </svg>
    <div v-if="low(r)" class="low-row"><span>年内已记录最低 <b>¥ {{f(low(r)!.price)}}</b></span><small>{{low(r)!.date}} 首次记录</small></div>
    <div class="period-summary"><span v-if="period(r)">区间均价 <b>¥ {{f(period(r)!.avg)}}</b> · 较期初 {{signed(period(r)!.change)}}（{{pct(period(r)!.percent)}}）</span><span v-else title="2025/01/01—2026/10/01，缺少期初基准价或连续历史，不能计算完整均价">区间均价 <span class="muted">历史不足</span></span><button class="card-detail" @click="openDetails(r.key)">明细 ↗</button></div>
   </article>
  </div>
  <div v-else class="empty-state"><div><strong>{{country}} · {{isSearching?'渠道搜索':attribute}}</strong><p v-if="isSearching">未找到匹配渠道，可输入部分名称、物流商或编码，如“云途 普货”“CHC”。</p><p v-else-if="!isMajorAttribute">该国家在此系统物流属性下暂无可展示的已发布渠道记录，可切换属性或搜索渠道。</p><p v-else>{{shortlist.listedCount?'该物流属性暂未匹配到可展示的表内渠道，可查看待确认项或调整搜索。':'原表未列出该国家 / 物流属性的主要发货渠道，可搜索其他真实渠道，补充清单后优先展示。'}}</p></div></div>
  <footer class="chart-footer"><span><span class="annual-legend">红色：年内已记录最低</span> · 最近五次发布 · 空缺不连线</span><div class="pager"><button :disabled="page<=1" @click="page--">上一页</button><span>{{page}} / {{pages}}</span><button :disabled="page>=pages" @click="page++">下一页</button></div></footer>
 </section>
 <p class="coverage-note">均价区间：2025/01/01—2026/10/01（639天）。现有版本记录始于2026/09，缺少完整年度和区间历史；不以现价倒填。金额不含财务折扣、关税及其他附加费。</p>
</main></div>
<div v-if="detailsOpen" class="detail-backdrop" @click.self="detailsOpen=false">
 <section class="detail-panel" role="dialog" aria-modal="true" aria-label="价格明细">
  <header><div><h2>真实价格明细</h2><p>{{country}} · {{isSearching?'搜索结果 · 全部物流属性':attribute}} · {{weight}} kg · CNY / 票</p></div><button class="close-details" @click="detailsOpen=false" aria-label="关闭价格明细">×</button></header>
  <div class="period-explainer"><b>去年元旦—今年10月1日 · 2025/01/01—2026/10/01</b><span>按生效天数加权，含首尾共639天；同日以最后发布版本计当日。缺少2025/01/01基准价时不计算均价。</span></div>
  <div class="detail-context">当前比较：<b>{{comparisonLabel}}</b><span>日期为系统发布时间，各渠道独立取最近三版</span></div>
  <table class="detail-table"><thead><tr><th>渠道 / 分区</th><th>前两版</th><th>上一版</th><th>本版</th><th>涨跌 / 幅度</th><th class="annual-low-text">年内已记录最低<small>首次记录日期</small></th><th>区间均价<small>较期初平均涨跌</small></th></tr></thead><tbody><tr v-for="r in detailRows" :key="r.key"><td :title="'系统渠道：'+r.channel.name">{{r.watchName}}<small>{{r.channel.provider}} · {{r.region}}</small><small>{{r.channel.name}}</small><small v-if="r.candidateFor?.length">待确认对应：{{r.candidateFor.join('、')}}</small><small>系统属性：{{r.channel.attribute}}<template v-if="r.temporaryEquivalent"> → {{r.tableAttribute}}（暂按等同）</template></small></td><td v-for="(v,i) in [compare(r).older,compare(r).previous,compare(r).current]" :key="i" :class="{'current':i===2,'annual-low-text':isLow(r,v)}" :title="v?.reason||v?.file">{{f(v?.price)}}<small v-if="v">V{{v.number}} · {{v.date}}</small><small v-else>无此历史版本</small><small v-if="v?.price==null&&v">{{v.reason}}</small></td><td :class="tone(compare(r).change)"><b>{{signed(compare(r).change)}}</b><small>{{pct(compare(r).percent)}}</small></td><td class="annual-cell"><b>{{f(low(r)?.price)}}</b><small>{{low(r)?.date||'暂无记录'}}</small></td><td class="period-cell"><b>{{period(r)?f(period(r)!.avg):'历史不足'}}</b><small>{{period(r)?signed(period(r)!.change)+' / '+pct(period(r)!.percent):'缺少期初或连续记录'}}</small></td></tr></tbody></table>
  <details v-for="r in detailRows" :key="r.key" class="history-records" :open="!!selected"><summary>{{r.channel.name}} · {{r.region}} · 查看全部 {{r.history.length}} 个已发布版本及来源</summary><table><thead><tr><th>版本 / 发布时间</th><th>每票运费</th><th>计费重 / kg</th><th>计价单价 / 挂号费</th><th>原始价格文件</th></tr></thead><tbody><tr v-for="v in [...r.history].reverse()" :key="v.id"><td>V{{v.number}} · {{publicationTime(v.timestamp)}}<small v-if="v.id===r.channel.current">当前版本</small></td><td :class="{'annual-low-text':isLow(r,v)}">{{f(v.price)}}<small v-if="v.price==null">{{v.reason}}</small></td><td>{{f(v.chargeWeight)}}</td><td>{{v.model==='per-piece-500g'?f(v.intervalPrice)+' / 票':f(v.rate)+' / kg'}} · {{f(v.fee)}}</td><td>{{v.file}}</td></tr></tbody></table></details>
  <div class="detail-note">物流属性优先排列原表的普货/服装、化妆品、保健品、带电，后接其他系统属性。原表有渠道名单的国家按原表顺序展示重点渠道，其他国家按系统物流属性展示渠道；选择其他属性时按系统实际属性展示对应渠道；输入搜索词后查询当前国家全部已启用渠道，涵盖全部物流属性，匹配的表内重点渠道优先。表外渠道显示系统原属性，不套用表内临时等同关系。物流属性沿用原表的普货/服装、化妆品、保健品、带电，同一渠道可分别出现在原表列出的各属性下，已确认的属性差异在对应表内渠道上暂按等同处理，仅用于价格展示，系统原属性保留。数据来自当前物流库留存的已发布 / 已替代版本，不含待审草稿。公斤价、挂号费、最低计费重及重量段按系统计费规则计算；图表各分区分别展示。财务折扣、税费等不在此比较口径内。<br/>日期采用北京时间的系统发布时间，不把原文件日期当作生效日；版本历史不证明发布前价格或整年价格已完整。年内已记录最低只在有记录的版本中比较。</div>
 </section>
</div>
</template>
<style scoped>

